use crate::aap::caps::kb_read;

const MAX_QUESTION_CHARS: usize = 512;

struct Node;

/// Truncate to at most `max` Unicode scalar values, matching Python's `len`.
fn bound_chars(s: &str, max: usize) -> String {
    match s.char_indices().nth(max) {
        Some((idx, _)) => s[..idx].to_string(),
        None => s.to_string(),
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let inner = query.query;

        // The precondition guarantees this bound already; enforcing it again
        // keeps the postcondition true regardless.
        let question = bound_chars(&inner.question, MAX_QUESTION_CHARS);

        let mut knowledge: Vec<String> = kb_read::lookup(&question);
        if knowledge.is_empty() {
            knowledge.push(String::from(
                "No relevant knowledge-base entries were found for this question.",
            ));
        }

        ConversationContext {
            intent: inner.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
